const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:d});
const compact=v=>Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(Number(v||0));
const statNames={STR:'Strength',END:'Endurance',AGI:'Agility',VIT:'Vitality',SPI:'Spirit',TEC:'Technique',GKI:'God ki'};
const statKeys=Array.isArray(STATS)?STATS.map(s=>typeof s==='string'?s:s.id):Object.keys(STATS);
const routeList=()=>Array.isArray(CATALOG.routes)?CATALOG.routes:Object.values(CATALOG.routes);
const routeCopy={earthling:['Earthling','Patient practice becomes exceptional technique. Develop discipline through varied, consistent training.'],saiyan:['Saiyan','Build battle control through strength and martial practice. Earn every breakthrough.'],hybrid:['Hybrid Saiyan','Balance physical training and focused practice to develop your hidden potential.'],namekian:['Namekian','Choose warrior strength, dragon spirit or balanced growth as your insight develops.'],android_infinite:['Infinite Android','Develop a reliable training engine through endurance and reactor control.'],android_bio:['Bio-Android','Adapt through exercise variety and the templates of your training partners.'],majin:['Majin','Develop body control and shape your growth with a deliberate set of partner cores.'],frieza_race:['Frieza Race','Build release control through disciplined training, then master each new state.']};
const paths=Object.keys(CATALOG.assets||{});
const asset=(path,fallback='images/v6/v6_hero.webp')=>encodeURI(paths.find(p=>p.toLowerCase()===path.toLowerCase())||(path.startsWith('images/v7/')?path:fallback));
const portrait=id=>`images/v7/portrait-${id}.webp`;
const portraitAttributes=id=>`src="${portrait(id)}" srcset="${portrait(id).replace('.webp','-mobile.webp')} 512w, ${portrait(id)} 1024w" sizes="(max-width:700px) 180px, 320px" decoding="async"`;
const art=(path,alt='',cls='')=>`<img class="${cls}" src="${esc(asset(path))}" ${path.startsWith('images/v7/')?`srcset="${esc(path.replace('.webp','-mobile.webp'))} 768w, ${esc(path)} 1536w" sizes="(max-width: 700px) 100vw, 900px"`:''} alt="${esc(alt)}" loading="lazy" decoding="async">`;
const partnerArt=id=>picture(partnerImage(id),'','partner-art');
const icons={today:'<path d="m3 11 9-8 9 8v10h-6v-7H9v7H3z"/>',train:'<path d="M6 5v14M3 8v8m15-11v14m3-11v8M6 12h12"/>',adventure:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',develop:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3z"/>',records:'<path d="M4 20V10m8 10V4m8 16V7M2 21h20"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',settings:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8m-4-4h8"/>',book:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Zm0 0v14"/>',flame:'<path d="M12 3c0 6-6 5-6 11a6 6 0 0 0 12 0c0-3-2-6-4-8 0 3-2 4-2 4"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.develop}</svg>`;
const btn=(label,action,attrs='',cls='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const meter=(v,max)=>`<div class="meter" role="progressbar" aria-label="Progress" aria-valuenow="${Math.min(Math.max(1,Math.round(Number(max)||1)),Math.max(0,Math.round(Number(v)||0)))}" aria-valuemin="0" aria-valuemax="${Math.max(1,Math.round(Number(max)||1))}"><span style="width:${Math.max(0,Math.min(100,100*(Number(v)||0)/Math.max(1,Number(max)||1)))}%"></span></div>`;
const byId=(a,id)=>a.find(x=>x.id===id);
const exById=id=>byId(CATALOG.exercises,id);
const sagaName=id=>byId(CATALOG.sagas,id)?.name||'A later chapter';
const pretty=name=>String(name||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const dateLabel=date=>{const d=new Date(`${String(date||'').slice(0,10)}T12:00:00`);return Number.isFinite(d.getTime())?d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):String(date||'Undated');};
let state=E.createState(),ui={booted:false,fatalLoad:false,replacing:false,finishing:false,page:'today',develop:'partners',adventure:'journey',records:'history',query:'',filter:'all',saveStatus:'Loading your adventure…',error:'',migration:null};
let saveChain=Promise.resolve(),epoch=0,draftTimeout,toastTimeout,timerInterval,returnFocus;
const character=()=>state.characters?.[state.activeCharacterId];
const settings=()=>state.settings||(state.settings={motion:true,sound:false});
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function saveIndicator(){document.querySelectorAll('[data-save-status]').forEach(el=>{el.textContent=ui.saveStatus;el.classList.toggle('error',!!ui.error)});const bar=$('#save-error');if(bar){bar.hidden=!ui.error;bar.innerHTML=ui.error?`${esc(ui.error)} ${ui.fatalLoad?`${btn('Retry loading','retry-load','','small')} ${btn('Import backup','import','','small ghost')}`:`${btn('Retry save','retry-save','','small')} ${btn('Export recovery copy','export','','small ghost')}`}`:'';}}
function persist(){if(ui.fatalLoad)return Promise.resolve(false);clearTimeout(draftTimeout);ui.saveStatus='Saving…';saveIndicator();saveChain=saveChain.catch(()=>{}).then(async()=>{const atEpoch=epoch;try{const draftTicket=draftRecovery.beginSave(state);const result=await S.saveGame(state);const draftResult=draftRecovery.confirmSave(draftTicket,result.state);if(atEpoch===epoch)state=result.state;else{state.revision=result.state.revision;state.savedAt=result.savedAt;}ui.error=[result.warning,...draftResult.warnings].filter(Boolean).join(' ');ui.saveStatus=`Saved ${new Date(result.savedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · on this device`;saveIndicator();return true;}catch(error){ui.error=error.message||'Your changes could not be saved. Export a recovery copy before closing.';ui.saveStatus='Changes not saved';saveIndicator();return false;}});return saveChain;}
function touchDraft(){epoch++;const checkpoint=draftRecovery.checkpoint(state);if(!checkpoint.ok)ui.error=checkpoint.error;ui.saveStatus=checkpoint.ok?'Draft protected · saving…':'Draft changed';saveIndicator();clearTimeout(draftTimeout);draftTimeout=setTimeout(persist,550);}
async function commit(action,message,type){if(ui.fatalLoad)return false;try{action();epoch++;render();const saved=await persist();if(saved&&message)notify(message);if(saved&&type)document.dispatchEvent(new CustomEvent('v7-feedback',{detail:{type,sound:!!settings().sound}}));return saved;}catch(error){notify(error.message||'This action could not be completed.');return false;}}
const draftRecovery=createDraftRecovery(globalThis);
let pendingRoutine=null;
const pluginHost={getState:()=>state,getCharacter:character,getView:()=>ui.restored||(ui.restored={}),escapeHTML:esc,save:async()=>{epoch++;return persist();},commit,openDialog,closeDialog,notify,render,searchRender,templates:()=>templateLibrary(state),templateEntries:t=>workoutFromDay({entries:normalizeTemplate(t).entries}),navigate:(page,section)=>{ui.page=page;if(page==='develop')ui.develop=section||'partners';if(page==='records')ui.records=section||'history';if(page==='adventure')ui.adventure=section||'journey';ui.query='';ui.filter='all';render();window.scrollTo({top:0,behavior:'instant'});},loadWorkout:async(entries,name)=>{if(character().draft?.entries?.length){pendingRoutine={entries:structuredClone(entries),name};openDialog('Replace the current draft?',`<p>Load ${esc(name)} after replacing the unfinished exercises? Your saved routine and completed sessions stay intact.</p><div class="button-row">${btn('Keep current draft','close-dialog','','ghost')}${btn('Load routine','restore-load-routine','','primary')}</div>`);return false;}character().draft={...freshDraft(),entries:structuredClone(entries),name};ui.page='train';epoch++;const ok=await persist();if(ok){closeDialog();render();}return ok;}};
const planner=createPlannerUI(pluginHost);
const restored=createRestoredUI(pluginHost);
const heading=(eye,title,body='',actions='')=>`<div class="page-heading"><div><p class="eyebrow">${esc(eye)}</p><h1>${esc(title)}</h1>${body?`<p class="muted">${esc(body)}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
const tabs=(items,active,action)=>`<div class="tabs" aria-label="Section">${items.map(([id,label])=>btn(esc(label),action,`data-id="${id}" aria-pressed="${id===active}"`,id===active?'selected':'ghost')).join('')}</div>`;
const empty=(title,desc)=>`<div class="empty-state"><span class="empty-icon">${icon('adventure')}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;
const activeSaga=()=>CATALOG.sagas.find(s=>!character().completedSagas.includes(s.id))||CATALOG.sagas.at(-1);
function render(){if(ui.fatalLoad){$('#app').innerHTML=`<main class="load-recovery card"><p class="eyebrow">YOUR ADVENTURE IS PROTECTED</p><h1>We could not open this save.</h1><p>Existing data has been left untouched. Retry loading or import a known backup to recover your adventure.</p><div id="save-error" role="alert" class="save-error"></div></main>`;saveIndicator();return;}const c=character();syncPageURL();document.documentElement.dataset.motion=settings().motion===false?'off':'on';if(!c){renderWelcome();saveIndicator();return;}const level=E.getLevel(c);$('#app').innerHTML=`<a class="skip-link" href="#main">Skip to content</a><div class="app-shell"><aside class="sidebar"><a class="brand" href="#today" data-action="nav" data-id="today"><span class="brand-mark">龍</span><span>DRAGON BALL<small>FITNESS RPG <b>VII</b></small></span></a><p class="sidebar-label">YOUR ADVENTURE</p><nav aria-label="Main navigation">${[['today','Today'],['train','Train'],['adventure','Adventure'],['develop','Develop'],['records','Records']].map(([id,label])=>`<button type="button" data-action="nav" data-id="${id}" class="nav-item ${ui.page===id?'active':''}" ${ui.page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='train'&&c.draft?'<i class="dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="long-road">${icon('adventure')}<p>A little stronger.<br>One session at a time.</p></div>${btn(`${icon('settings')} Settings & backup`,'settings','','ghost sidebar-settings')}<p class="save-status" data-save-status>${esc(ui.saveStatus)}</p></div></aside><div class="main-shell"><header class="topbar"><button class="character-switch" data-action="characters"><span class="avatar"><img ${portraitAttributes(c.routeId)} alt=""></span><span><b>${esc(c.name)}</b><small>${esc(routeCopy[c.routeId]?.[0]||c.race)} · Level ${level.level}</small></span><span class="chevron">⌄</span></button><div class="wallet" aria-label="Training currencies"><button class="wallet-currency" data-action="r-open-develop" data-id="equipment" aria-label="${num(c.tp,2)} Training Points. Open equipment."><i class="currency tp">T</i><b>${c.tp>=10000?compact(c.tp):num(c.tp,1)}</b><small>TP</small></button><button class="wallet-currency" data-action="r-open-develop" data-id="abilities" aria-label="${num(c.ap,2)} Ability Points. Open abilities."><i class="currency ap">A</i><b>${c.ap>=10000?compact(c.ap):num(c.ap,1)}</b><small>AP</small></button></div><button class="mobile-settings icon-button" aria-label="Settings and backup" data-action="settings">${icon('settings')}</button></header><div id="save-error" role="alert" class="save-error" hidden></div>${ui.migration?`<div class="migration-banner"><div><b>Your previous adventure is safe.</b><p>${esc(typeof ui.migration==='string'?ui.migration:ui.migration.summary||'Your characters and training history were migrated into a separate v7 save. The original v6 save remains intact. Your previous rewards are preserved. Search conversions and retained progress are recorded on the Dragon Ball search page.')}</p></div>${btn('Dismiss','dismiss-migration','','small ghost')}</div>`:''}<main id="main" tabindex="-1">${({today:renderToday,train:renderTrain,adventure:renderAdventure,develop:renderDevelop,records:renderRecords}[ui.page]||renderToday)()}</main><footer class="page-footer"><span>DRAGON BALL FITNESS RPG · V7</span><span data-save-status>${esc(ui.saveStatus)}</span></footer></div><nav class="bottom-nav" aria-label="Mobile navigation">${[['today','Today'],['train','Train'],['adventure','Adventure'],['develop','Develop'],['records','Records']].map(([id,label])=>`<button type="button" data-action="nav" data-id="${id}" class="${ui.page===id?'active':''}" ${ui.page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('')}</nav></div>`;saveIndicator();updateTimer();}
function characterForm(){return `<form id="character-form"><label>Character name<input name="name" required maxlength="40" placeholder="Your name" autocomplete="nickname"></label><fieldset class="route-fieldset"><legend>Choose your origin</legend><div class="route-picker">${routeList().map((r,i)=>`<label class="route-option"><input type="radio" name="routeId" value="${r.id}" ${i===0?'checked':''}><span><img ${portraitAttributes(r.id)} alt=""><b>${esc(routeCopy[r.id]?.[0]||r.label)}</b></span></label>`).join('')}</div></fieldset><p class="route-description" id="route-description">${esc(routeCopy[routeList()[0]?.id]?.[1])}</p><button class="button primary wide" type="submit">Begin chapter one ${icon('arrow')}</button></form>`;}
function renderWelcome(){$('#app').innerHTML=`<main class="welcome"><div class="welcome-art">${art('images/v7/mountain-dawn.webp','Mountains at dawn, at the beginning of a new adventure')}<div class="welcome-shade"></div><a class="brand" href="#"><span class="brand-mark">龍</span><span>DRAGON BALL<small>FITNESS RPG <b>VII</b></small></span></a><div class="welcome-story"><p class="eyebrow">EVERY LEGEND STARTS SOMEWHERE</p><h1>Your power.<br>Your long road.</h1><p>Somewhere in the mountains, a girl is looking for seven Dragon Balls. Your first chapter is about to begin.</p><div class="welcome-pills">${tag('8 distinct training paths')}${tag('38 story sagas')}${tag('One real workout at a time')}</div></div></div><section class="welcome-form"><p class="eyebrow">CHAPTER ZERO</p><h2>Begin your adventure</h2><p class="muted">Build a character through your real training. Learn from the series cast, invest in your growth, and earn your transformations over a journey measured in years.</p>${characterForm()}<div class="welcome-restore">Already have a save? ${btn('Import backup','import','','text-button')}</div><p class="fine-print">Your adventure is saved on this device. Regular exports keep it yours. The first workout can be as simple as a walk.</p><p class="save-status" data-save-status>${esc(ui.saveStatus)}</p><div id="save-error" role="alert" class="save-error" hidden></div></section></main>`;}
function renderToday(){return renderDashboard(character(),state,ui.restored||{});}
const freshDraft=()=>({date:E.localDate(),name:'Training session',kind:'training',notes:'',rpe:null,rir:null,recovery:structuredClone(character()?.recovery||{}),entries:[]});
function draft(){const c=character();return c.draft||(c.draft=freshDraft());}
const isTimed=ex=>ex?.type==='timed_hold';
const isCardio=ex=>['cardio_duration','cardio_distance'].includes(ex?.type);
const allTemplates=()=>[...CATALOG.templates.map((t,i)=>({...t,id:t.id||`default-${i}`,builtin:true})),...(state.templates||[])];
const draftField=(label,key,type='text',attrs='')=>`<label>${label}<input type="${type}" data-draft="${key}" value="${esc(draft()[key]??'')}" ${attrs}></label>`;
function entryEditor(entry,index){const ex=exById(entry.exerciseId)||{name:entry.exerciseId,type:'bodyweight'},timed=isTimed(ex),cardio=isCardio(ex);return `<section class="exercise-card"><div class="exercise-header"><div><p class="eyebrow">${esc(ex.category)} · ${esc(ex.group||ex.type)}</p><h3>${esc(ex.name)}</h3></div><button class="icon-button" data-action="remove-exercise" data-index="${index}" aria-label="Remove ${esc(ex.name)}">${icon('close')}</button></div>${cardio?`<div class="form-grid"><label>Duration · minutes<input type="number" min="0" max="1440" step="0.1" inputmode="decimal" data-entry="${index}" data-entry-field="duration" value="${esc(entry.duration||'')}"></label>${ex.type==='cardio_distance'?`<label>Distance · km<input type="number" min="0" max="500" step="0.01" inputmode="decimal" data-entry="${index}" data-entry-field="distance" value="${esc(entry.distance||'')}"></label>`:''}</div>`:`<div class="set-table"><div class="set-table-head"><span>SET</span><span>${timed?'SECONDS':'REPS'}</span><span>${ex.type==='weighted'?'LOAD · KG':timed?'':'EXTRA KG'}</span><span></span></div>${(entry.sets||[]).map((set,j)=>`<div class="set-row"><span class="set-number">${j+1}</span><input aria-label="${esc(ex.name)} set ${j+1} ${timed?'seconds':'reps'}" type="number" min="0" max="${timed?'14400':'1000'}" step="1" inputmode="numeric" data-entry="${index}" data-set="${j}" data-set-field="${timed?'seconds':'reps'}" value="${esc(set[timed?'seconds':'reps']??'')}">${timed?'<span></span>':`<input aria-label="${esc(ex.name)} set ${j+1} weight in kilograms" type="number" min="0" max="1000" step="0.5" inputmode="decimal" data-entry="${index}" data-set="${j}" data-set-field="weight" value="${esc(set.weight??0)}">`}<button class="icon-button" data-action="remove-set" data-index="${index}" data-set="${j}" aria-label="Remove set ${j+1}">${icon('close')}</button></div>`).join('')}</div>${btn(`${icon('plus')} Add set`,'add-set',`data-index="${index}"`,'ghost small')}`}<details class="entry-extra"><summary>Notes & rest · ${num(entry.restSeconds||90)} sec</summary><label>Exercise notes<input type="text" maxlength="2000" data-entry="${index}" data-entry-field="notes" value="${esc(entry.notes||'')}"></label><div class="button-row"><label>Rest seconds<input type="number" min="0" max="3600" step="15" data-entry="${index}" data-entry-field="restSeconds" value="${num(entry.restSeconds??90)}"></label>${btn('Start exercise rest','timer-entry',`data-index="${index}"`,'ghost')}</div></details><p class="exercise-benefit">Develops ${Object.keys(ex.stat||ex.weights||{}).filter(s=>s!=='GKI'||character().earnedBands.includes('divine')).map(s=>statNames[s]||s).join(' · ')||'your discipline'} · ${num(E.getBoosts(character(),ex).total,2)}× growth</p></section>`;}
function boostRows(b){return `<div class="boost-rows">${[['race','Race development'],['partners','Training partners'],['equipment','In-game equipment'],['abilities','Abilities'],['mastery','Form mastery']].map(([key,label])=>`<div><span>${label}</span><b>×${num(b[key]??1,3)}</b></div>`).join('')}<div class="boost-total"><span>Multiplied together</span><b>×${num(b.total,3)}</b></div></div>`;}
function learningRows(){const b=E.getLearningBoosts(character());return `<p class="eyebrow learning-label">LEARNING & CURRENCY</p><div class="boost-rows">${[['xp','Character XP'],['bond','Partner XP'],['tp','Training points']].map(([key,label])=>`<div><span>${label}</span><b>×${num(b[key],3)}</b></div>`).join('')}</div>`;}
function renderTrain(){const c=character(),d=draft(),recordedBuild=c.workouts.find(w=>w.date===d.date&&!w.legacy&&w.receipt)?.receipt.snapshot||c.dailySnapshots?.[d.date];return `${heading(d.legacyCorrectionId?'CORRECT THE PHYSICAL RECORD':d.editId?'REVISE YOUR RECORD':'YOUR TRAINING SANCTUARY',d.legacyCorrectionId?'Preserve the past. Correct the record.':d.editId?'Edit this session.':'Real work. Lasting power.','Log what you actually did. Your draft saves as you go.',btn('Templates','templates','','ghost'))}${d.legacyCorrectionId?`<section class="card"><p>These edits update historical exercise records and analytics. They award no XP or currencies and leave your original v6 entry and stat balance intact.</p><label>Reason for correction<textarea data-draft="correctionReason" maxlength="2000" required>${esc(d.correctionReason||'')}</textarea></label></section>`:''}<div class="training-layout"><div class="training-main"><section class="card"><div class="form-grid">${draftField('Session name','name','text','maxlength="100"')}${draftField('Date','date','date',`max="${E.localDate()}" required`)}</div></section><div class="exercise-list">${d.entries.length?d.entries.map(entryEditor).join(''):`<section class="training-empty"><div class="sanctuary-art">${art('images/v7/turtle-sanctuary.webp','An island training sanctuary')}</div><div><p class="eyebrow">MAKE YOUR FIRST MOVE</p><h2>Today’s work begins here.</h2><p>Search the full exercise library or start from a template. Choose the load and pace that fit you.</p>${btn(`${icon('plus')} Add an exercise`,'exercises','','primary')}</div></section>`}</div>${d.entries.length?btn(`${icon('plus')} Add exercise`,'exercises','','wide dashed'):''}<section class="card session-reflection"><h2>How did it feel?</h2><div class="form-grid">${draftField('Session effort · RPE 1–10','rpe','number','min="1" max="10" step="0.5" inputmode="decimal" placeholder="Optional"')}${draftField('Reps in reserve · RIR 0–10','rir','number','min="0" max="10" step="1" inputmode="numeric" placeholder="Optional"')}</div><label>Session notes<textarea rows="3" data-draft="notes" maxlength="4000" placeholder="Technique cues, how you felt, what to try next…">${esc(d.notes)}</textarea></label><div class="check-row">${['illness','injury','deload'].map(key=>`<label><input type="checkbox" data-recovery="${key}" ${d.recovery?.[key]?'checked':''}>${key==='deload'?'Easier week':key==='illness'?'Feeling unwell':'Managing an injury'}</label>`).join('')}</div><p class="fine-print">These flags guide recovery feedback. A lighter session or a rest day never takes away your earned power.</p></section><div class="session-finish"><span class="save-status" data-save-status>${esc(ui.saveStatus)}</span><div class="button-row">${btn('Discard draft','discard-draft','','ghost')}${btn(d.legacyCorrectionId?'Save historical correction':d.editId?'Save session changes':'Finish & save session','finish-workout','','primary')}</div></div></div><aside class="training-aside"><section class="card timer-card"><p class="eyebrow">REST BETWEEN SETS</p><div class="timer-display" id="timer-display" aria-live="off">01:30</div><div class="timer-presets">${[60,90,120,180].map(s=>btn(`${s/60}m`,'timer-start',`data-seconds="${s}"`,'ghost small')).join('')}</div><div class="button-row">${btn('Start 90 sec','timer-start','data-seconds="90"','primary small')}${btn('Reset','timer-reset','','ghost small')}</div><p class="fine-print">Use the rest time that suits your training.</p></section><section class="card build-summary"><p class="eyebrow">YOUR CURRENT TRAINING BUILD</p>${recordedBuild&&!d.legacyCorrectionId?`<p class="info-note">Rewards for ${esc(d.date)} use the build saved with the first entry on that date${recordedBuild.summary?.total?` (×${num(recordedBuild.summary.total,2)} general growth)`:""}. Later changes to partners, upgrades and techniques apply from your next training date.</p>`:""}<h2>${num(E.getBoosts(c).total,2)}× growth</h2>${boostRows(E.getBoosts(c))}${learningRows()}${btn('Develop your build','nav','data-id="develop"','ghost wide')}</section><section class="card"><h3>Keep this routine</h3><p class="muted">Save the exercise order and sets for your next session.</p>${btn('Create template','save-template','','ghost wide')}</section></aside></div>`;}
function renderAdventure(){const c=character();return `${heading('FOLLOW THE SERIES','A world worth training for.','From a chance meeting in the mountains to the edge of mortal potential.')}${tabs([['journey','Saga journey'],['story','Story archive'],['expedition','Dragon Balls']],ui.adventure,'adventure-tab')}${ui.adventure==='story'?restored.story():ui.adventure==='expedition'?renderExpedition():`<div class="journey-intro"><span class="radar-mini"><i></i></span><p><b>${c.completedSagas.length} of ${CATALOG.sagas.length} chapters completed</b><br><span class="muted">Earn power through training. Explore each chapter, then pursue its mastery.</span></p></div>${c.completedSagas.length?`<section class="card replay-controls"><h2>Revisit a chapter</h2><p class="muted">Choose a cleared saga to build replay focus, or keep training in your current chapter. Each replay costs 100 new focus.</p><div class="button-row"><label>Training focus<select id="focus-saga"><option value="">Current chapter</option>${CATALOG.sagas.filter(s=>c.completedSagas.includes(s.id)).map(s=>`<option value="${s.id}" ${c.focusSagaId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${btn('Set training focus','set-focus-saga','','ghost')}</div><p class="fine-print">A saved day keeps its original focus. Changes apply to the next training date.</p></section>`:''}<div class="saga-timeline">${CATALOG.sagas.map((saga,index)=>{const s=E.getSagaState(c,saga.id);return `<article class="saga-card ${s.status}" id="saga-${saga.id}"><div class="saga-number">${String(index+1).padStart(2,'0')}</div><div class="saga-image">${art(`images/saga_banners/${saga.id}.webp`)}<span class="saga-status">${s.status.toUpperCase()}</span></div><div class="saga-body">${tag(saga.series)}<h2>${esc(saga.name)}</h2><p>${esc(saga.desc)}</p><div class="saga-goals"><span>Base power <b>${num(s.baseRequired)}</b></span><span>Story XP <b>${num(s.storyRequired)}</b></span><span>Focus <b>${num(s.focus,1)} / ${num(s.focusRequired)}</b></span></div>${meter(s.focus,s.focusRequired)}<p class="lock-reason">${esc(s.reason||'This chapter is ready to complete.')}</p><div class="button-row">${s.canClear?btn('Complete chapter','clear-saga',`data-id="${saga.id}"`,'primary small'):s.status==='cleared'?btn('Pursue mastery','master-saga',`data-id="${saga.id}"`,'small'):''}${s.status!=='locked'?btn('Read chapter','saga-story',`data-id="${saga.id}"`,'ghost small'):''}${['cleared','mastered'].includes(s.status)?btn(`Replay · ${num(s.replayProgress,0)} / ${s.replayRequired}`,'replay-saga',`data-id="${saga.id}" ${s.canReplay?'':'disabled'}`,'ghost small'):''}</div></div></article>`}).join('')}</div>`}`;}
function renderStory(){const entries=E.getStoryEntries(character()).filter(e=>(ui.filter!=='unread'||!e.read)&&`${e.title} ${e.series} ${e.text}`.toLowerCase().includes(ui.query.toLowerCase()));return `<div class="toolbar"><label class="search-field">Search your story<input type="search" id="page-search" data-query value="${esc(ui.query)}" placeholder="Character, chapter, moment…"></label><label>Show<select data-filter><option value="all" ${ui.filter==='all'?'selected':''}>All unlocked entries</option><option value="unread" ${ui.filter==='unread'?'selected':''}>Unread entries</option></select></label></div><p class="collection-count">${entries.length} unlocked story entries · New moments appear as you train and develop relationships.</p><div class="story-grid">${entries.map(e=>`<button class="story-card" data-action="story-reader" data-id="${esc(e.id)}"><span class="story-icon">${icon('book')}</span><div>${tag(e.series||e.kind||'STORY')}<h3>${esc(e.title)}</h3><p>${esc(String(e.text||'').slice(0,150))}…</p><span class="read-status">${e.read?'Read':'New story'} ${icon('arrow')}</span></div></button>`).join('')||empty('The next page is waiting.','Keep training and spending time with your partners to unlock more story.')}</div>`;}
function renderExpedition(){return restored.balls();}
function equipmentList(){return Array.isArray(CATALOG.trainingBranches)?CATALOG.trainingBranches.flatMap(branch=>(branch.upgrades||[]).map(item=>({...item,branch:branch.id}))):Object.entries(CATALOG.trainingBranches).flatMap(([branch,items])=>(Array.isArray(items)?items:items.upgrades||[]).map(item=>({...item,branch})));}
const collectionMatch=(item,owned,available)=>`${item.name} ${item.desc||''} ${item.role||''} ${item.era||''}`.toLowerCase().includes(ui.query.toLowerCase())&&(ui.filter==='all'||ui.filter==='owned'&&owned||ui.filter==='available'&&available||ui.filter==='locked'&&!owned&&!available);
function renderDevelop(){const c=character();let content='';if(ui.develop==='race')content=renderRace()+restored.raceExtras();else{const kind=ui.develop,source=kind==='partners'?CATALOG.partners:kind==='abilities'?CATALOG.abilities:kind==='forms'?CATALOG.transformations:equipmentList(),fn=kind==='partners'?E.getPartnerState:kind==='abilities'?E.getAbilityState:kind==='forms'?E.getFormState:E.getEquipmentState;const items=source.map(item=>({item,s:fn(c,item.id)})).filter(({item,s})=>collectionMatch(item,s.owned||s.rank>0||s.level>0&&kind==='equipment'||s.unlocked,s.canBuy||s.canUnlock));content=`${restored.slotPanel(kind)}${kind==='equipment'?'<p class="info-note">These are fictional in-game upgrades. They increase your character’s training gains and are not instructions to wear weighted gear or change your real exercise.</p>':''}<div class="toolbar"><label class="search-field">Search collection<input id="page-search" type="search" data-query value="${esc(ui.query)}" placeholder="Find your next investment…"></label><label>Show<select data-filter>${[['all','All'],['owned','Owned'],['available','Available now'],['locked','Locked']].map(([id,label])=>`<option value="${id}" ${ui.filter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="collection-summary"><span>${items.length} of ${source.length} ${kind}</span><span>${kind==='partners'?`${c.activePartners.length} / ${E.getPartnerSlots?.(c)||2} active partners`:kind==='abilities'?`${c.activeAbilities.length} / ${E.getAbilitySlots(c)} equipped abilities`:kind==='forms'?`Current: ${E.getPower(c).formName}`:'Upgrades multiply permanent training gains'}</span></div><div class="collection-grid ${kind}">${items.map(({item,s})=>collectionCard(kind,item,s)).join('')||empty('No matches in this collection.','Try a different search or filter.')}</div>`;}return `${heading('BUILD THE WAY YOU GROW','Power has a practice.','Partners, equipment, techniques and mastery shape every training session.',btn(`${num(E.getBoosts(c).total,2)}× growth · See why`,'boosts','','ghost'))}${tabs([['partners','Partners'],['equipment','Equipment'],['abilities','Abilities'],['race','Race path'],['forms','Transformations']],ui.develop,'develop-tab')}${content}`;}
function effectSummary(effects){const labels={statAll:'Broad stat growth',characterXP:'Partner XP',txp:'Character XP',tp:'Training points',sp:'Technique focus',weighted:'Weighted exercise',bodyweight:'Bodyweight exercise',timed_hold:'Holds',cardio_distance:'Distance work',cardio_duration:'Timed work'};const result=[];for(const[k,v]of Object.entries(effects||{})){if(typeof v==='number'&&v>0)result.push(labels[k]||pretty(k));else if(v&&typeof v==='object')for(const[sub,n]of Object.entries(v))if(typeof n==='number'&&n>0)result.push(statNames[sub]||labels[sub]||pretty(sub));}return `Focus: ${result.slice(0,6).join(' · ')}`;}
function collectionCard(kind,item,s){const owned=kind==='partners'?s.owned:kind==='equipment'?s.level>0:kind==='abilities'?s.rank>0:s.unlocked;let visual='',actions='',meta='',detail=item.desc;
if(kind==='partners'){visual=`<div class="collection-art">${partnerArt(item.id)}${tag(item.era||'DB','art-tag')}</div>`;meta=owned?`Partner Level ${s.level}`:item.tier||'Training partner';detail=item.role;actions=owned?btn(s.active?'In your team':'Equip partner','toggle-partner',`data-id="${item.id}"`,s.active?'selected':'primary'):btn(s.canBuy?`Recruit · ${num(s.cost)} TP`:'Partner locked','recruit-partner',`data-id="${item.id}" ${s.canBuy?'':'disabled'}`,'primary');actions+=btn('Details','partner-detail',`data-id="${item.id}"`,'ghost small');}
if(kind==='equipment'){visual=equipmentPicture(item.id);meta=`Level ${s.level} / ${s.maxLevel}`;actions=btn(s.level>=s.maxLevel?'Fully developed':s.canBuy?`Upgrade · ${num(s.cost)} TP`:'Upgrade locked','buy-equipment',`data-id="${item.id}" ${s.canBuy?'':'disabled'}`,s.level>=s.maxLevel?'selected':'primary');}
if(kind==='abilities'){visual=abilityPicture(item.id);meta=s.rank?`Ability Level ${s.practiceLevel} / 100`:'Learn with AP · develop through practice';actions=btn(s.rank>=s.maxRank?'Learned':s.canBuy?`${s.rank?'Upgrade':'Learn'} · ${num(s.cost)} AP`:'Technique locked','buy-ability',`data-id="${item.id}" ${s.canBuy?'':'disabled'}`,s.rank>=s.maxRank?'selected':'primary');if(owned)actions+=btn(s.active?'Prepared':'Prepare','toggle-ability',`data-id="${item.id}"`,s.active?'selected small':'ghost small');actions+=btn('Practice & effects','r-ability-detail',`data-id="${item.id}"`,'ghost small');}
if(kind==='forms'){visual=`<div class="form-art" style="--aura:${auraColour(item.id)}">${picture(imagePath(FORM_ART[item.id]),item.name)}<div class="form-aura"></div></div>`;meta=s.bandId?`×${num(s.multiplier,1)} power${s.level?` · Mastery ${s.level}`:" · Not unlocked"}`:"Another race route";actions=s.unlocked?btn(s.equipped?'Current form':'Equip form','equip-form',`data-id="${item.id}"`,s.equipped?'selected':'primary'):btn(s.canUnlock?'Unlock form':'Form locked','unlock-form',`data-id="${item.id}" ${s.canUnlock?'':'disabled'}`,'primary');actions+=btn('Mastery & echoes','r-form-detail',`data-id="${item.id}"`,'ghost small');}
return `<article class="collection-card collection-${kind} ${owned?'owned':''}">${visual}<div class="collection-body"><p class="eyebrow">${esc(meta)}</p><h3>${esc(item.name)}</h3>${owned&&['partners','abilities','forms'].includes(kind)?`${meter(s.xpInto,s.xpNeeded)}<p class="collection-level-meta">${num(s.xpInto,1)} / ${num(s.xpNeeded)} XP${s.nextMilestone?` · Next: ${esc(s.nextMilestone.name)} at Level ${s.nextMilestone.level}`:''}</p>`:''}<p class="collection-description">${esc(detail||'Develop this part of your training build.')}</p>${kind==='forms'?renderFormCombat(character(),item.id,{compact:true}):''}${kind!=='forms'?`<p class="effect-text">${esc(effectSummary(kind==='abilities'?{stat:s.specialty}:item.effects||item.effectsPerLevel))}</p>`:''}<p class="lock-reason">${esc(s.reason||(owned?'Part of your journey.':'Ready for your next investment.'))}</p><div class="collection-actions">${actions}</div></div></article>`;}
function renderRace(){const c=character(),r=E.getRouteState(c),p=E.getPower(c),release=E.getEarnedRelease(c);return `<section class="race-hero card"><div class="race-hero-art"><div class="aura aura-one"></div><img ${portraitAttributes(c.routeId)} alt="${esc(r.name)}"></div><div><p class="eyebrow">${esc(routeCopy[c.routeId]?.[0])} DEVELOPMENT</p><h2>${esc(r.name)}</h2><p>${esc(r.description||routeCopy[c.routeId]?.[1])}</p><div class="race-resource"><span>${esc(r.resourceName)}</span><b>${num(r.resource,1)}</b></div><p class="muted">Current state: ${esc(p.formName)} · ×${num(p.multiplier)} power</p>${release.bandId!=='base'?`<div class="native-release"><p class="fine-print">Earned race release: ${esc(release.name)} · ×${num(release.multiplier)} power</p>${btn(release.equipped?'Native release active':'Use native release','equip-release','',release.equipped?'selected small':'ghost small')}</div>`:''}${r.branches?.length?`<div class="branch-picker"><label>Training specialisation<select id="race-branch">${r.branches.map(b=>`<option value="${esc(typeof b==='string'?b:b.id)}" ${(typeof b==='string'?b:b.id)===c.branch?'selected':''}>${esc(typeof b==='string'?pretty(b):b.name||b.label)}</option>`).join('')}</select></label>${btn('Choose branch','set-branch','','small')}</div>`:''}${['majin','android_bio'].includes(c.routeId)?`<div class="core-picker"><label>${c.routeId==='majin'?'Partner core':'Adaptation template'}<select id="core-partner"><option value="">Choose a recruited partner</option>${Object.keys(c.partners).map(id=>`<option value="${id}">${esc(byId(CATALOG.partners,id)?.name||id)}</option>`).join('')}</select></label>${btn('Toggle selection','equip-core','','small')}<p class="fine-print">Selected: ${(c.cores||[]).map(id=>esc(byId(CATALOG.partners,id)?.name||id)).join(', ')||'None'}</p></div>`:''}</div></section><h2 class="subheading">Your path to full power</h2><p class="muted">Named forms use their own power multipliers. Earned route potential is a separate native release you can select above.</p><div class="awakening-path">${r.tiers.map((t,i)=>`<article class="awakening-tier ${t.earned?'earned':''}"><span class="tier-index">${t.earned?icon('check'):String(i+1).padStart(2,'0')}</span><div><p class="eyebrow">${esc(t.bandId==='base'?'Your first chapter':sagaName(t.sagaId))}</p><h3>${esc(t.name)}</h3><p class="muted">${esc(t.reason||'Your power develops through training and the story.')}</p></div><div class="tier-action">${renderTierPower(t)}${t.earned?tag('Earned','success'):btn(t.canUnlock?'Awaken':'Locked','awaken',`data-id="${esc(t.bandId||t.id)}" ${t.canUnlock?'':'disabled'}`,'small primary')}</div></article>`).join('')}</div>`;}
function renderRecords(){return `${heading('THE WORK BEHIND THE POWER','Proof of your practice.','Your sessions, stats and the stories they unlock.',btn('Project training','r-projection','','ghost'))}${tabs([['history','History'],['analysis','Calendar & analysis'],['records','Personal records'],['body','Body weight'],['stats','Stat growth'],['rewards','Goals & rewards'],['compare','Benchmarks & Player 2']],ui.records,'records-tab')}${ui.records==='records'?restored.records():ui.records==='body'?renderBody():ui.records==='stats'?renderStatSheet(character(),state,ui.restored?.statRange||'30')+renderGrowthPlot(character(),state,ui.restored?.chart||{}):ui.records==='analysis'?restored.analysis():ui.records==='rewards'?restored.rewards():ui.records==='compare'?restored.comparisonView():renderHistory()}`;}
function renderHistory(){const c=character(),workouts=c.workouts.map(w=>({...w,...getEffectivePhysicalRecord(w)})).sort((a,b)=>String(b.date).localeCompare(String(a.date))),filtered=workouts.filter(w=>`${w.name} ${w.notes||''}`.toLowerCase().includes(ui.query.toLowerCase()));return `<div class="records-summary"><section class="metric-card"><span class="eyebrow">TRAINING SESSIONS</span><strong>${workouts.filter(w=>w.kind!=='rest').length}</strong></section><section class="metric-card"><span class="eyebrow">RECOVERY DAYS</span><strong>${new Set(workouts.filter(w=>w.kind==='rest').map(w=>w.date)).size}</strong></section><section class="metric-card"><span class="eyebrow">STORY EXPERIENCE</span><strong>${compact(c.storyXP)}</strong></section></div><section class="card"><h2>The last eight weeks</h2>${activityChart(workouts)}</section><div class="toolbar"><label class="search-field">Search sessions<input type="search" id="page-search" data-query value="${esc(ui.query)}" placeholder="Session name or notes…"></label></div><div class="history-list">${filtered.map(w=>`<article class="history-card"><span class="activity-icon">${icon(w.kind==='rest'?'flame':'train')}</span><div class="history-title"><h3>${esc(w.name||'Training session')}</h3><p>${dateLabel(w.date)} · ${w.kind==='rest'?'Recovery day':`${w.entries?.length||0} exercises`}${w.legacy?' · Imported archive':''}${w.hasPhysicalCorrection?' · Corrected physical record':''}</p>${w.notes?`<p class="history-notes">${esc(w.notes)}</p>`:''}</div><div class="button-row">${btn('View','workout-detail',`data-id="${esc(w.id)}"`,'ghost small')}${!w.legacy?`${btn('Edit notes','edit-notes',`data-id="${esc(w.id)}"`,'ghost small')}${btn('Delete','delete-workout',`data-id="${esc(w.id)}"`,'text-button small danger')}`:''}</div></article>`).join('')||empty('Your training story starts with one entry.','Finished sessions and recovery days will appear here.')}</div>`;}
function activityChart(workouts){const now=new Date(`${E.localDate()}T12:00:00`),weeks=Array.from({length:8},(_,i)=>{const end=new Date(now);end.setDate(end.getDate()+1-(7-i)*7);const start=new Date(end);start.setDate(start.getDate()-7);const count=workouts.filter(w=>{const d=new Date(`${w.date}T12:00:00`);return w.kind!=='rest'&&d>=start&&d<end;}).length;return{count,label:start.toLocaleDateString(undefined,{day:'numeric',month:'short'})};}),max=Math.max(3,...weeks.map(w=>w.count));return `<div class="activity-chart" role="img" aria-label="Sessions per week: ${weeks.map(w=>`${w.label}: ${w.count}`).join('; ')}">${weeks.map(w=>`<div class="chart-column"><span>${w.count}</span><i style="height:${Math.max(3,w.count/max*100)}px"></i><small>${w.label}</small></div>`).join('')}</div>`;}
function renderPRs(){const records=E.getRecords(character());return `<section class="card"><div class="section-top"><h2>Your personal bests</h2>${tag(`${records.length} records`)}</div><p class="muted">Compare your own training over time. These records reflect the sessions you log.</p><div class="pr-grid">${records.map(r=>`<article class="pr-card">${icon('develop')}<h3>${esc(r.name)}</h3><strong>${num(r.value,2)} <small>${esc(r.unit)}</small></strong><p>${dateLabel(r.date)}</p></article>`).join('')||empty('Give your future self a benchmark.','Log a session to start building your personal records.')}</div></section>`;}
function renderBody(){const log=[...(character().bodyWeightLog||[])].sort((a,b)=>String(a.date).localeCompare(String(b.date))),last=log.at(-1),first=log[0];return `<div class="body-layout"><section class="card"><p class="eyebrow">BODY WEIGHT JOURNAL</p><h2>One measure. Your context.</h2><p class="muted">Keep an optional record in kilograms. Weight changes do not determine your worth or your character’s power.</p><form id="body-form"><div class="form-grid"><label>Date<input name="date" type="date" value="${E.localDate()}" max="${E.localDate()}" required></label><label>Weight · kg<input name="weight" type="number" min="20" max="500" step="0.1" inputmode="decimal" required placeholder="kg"></label></div><button class="button primary" type="submit">Save measurement</button></form></section><section class="card"><p class="eyebrow">LATEST MEASUREMENT</p><div class="large-number">${last?num(last.weight,1):'—'}<small>kg</small></div><p class="muted">${last?dateLabel(last.date):'No measurements yet'}</p>${log.length>1?`<p>${num(last.weight-first.weight,1)} kg from first entry · ${log.length} entries</p>${weightChart(log)}`:''}</section></div><section class="card"><h2>Measurement history</h2>${log.length?[...log].reverse().map(w=>`<div class="activity-row"><span><b>${num(w.weight,1)} kg</b><small>${dateLabel(w.date)}</small></span>${btn('Remove','delete-body',`data-id="${esc(w.id||w.date)}"`,'text-button small danger')}</div>`).join(''):empty('No measurements yet.','This journal is completely optional.')}</section>`;}
function weightChart(log){const v=log.map(w=>Number(w.weight)),min=Math.min(...v)-1,max=Math.max(...v)+1,points=v.map((w,i)=>`${10+i/(v.length-1)*280},${100-(w-min)/(max-min)*80}`).join(' ');return `<svg class="weight-chart" viewBox="0 0 300 110" role="img" aria-label="Body weight history from ${v[0]} to ${v.at(-1)} kilograms"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg>`;}
function renderStats(){const c=character(),max=Math.max(...statKeys.map(s=>Number(c.stats[s]||0)),1),p=E.getPower(c);return `<section class="card stat-overview"><div><p class="eyebrow">PERMANENT DEVELOPMENT</p><h2>Every point has a history.</h2><p class="muted">Your real exercise develops these stats. Your current state multiplies base power; your training build multiplies the gains that stay.</p><div class="power-equation"><b>${num(p.base,1)}</b><span>base</span><i>×</i><b>${num(p.multiplier)}</b><span>state</span><i>=</i><b>${compact(p.effective)}</b></div>${btn('See training boost arithmetic','boosts','','ghost')}</div><div class="stat-bars">${statKeys.map(s=>`<div class="stat-row"><span>${esc(statNames[s]||s)}</span><b>${num(c.stats[s],2)}</b>${meter(c.stats[s],max)}</div>`).join('')}</div></section><section class="card"><h2>Collection milestones</h2><div class="collection-milestones">${[['Partners recruited',Object.keys(c.partners).length,CATALOG.partners.length],['Abilities learned',Object.keys(c.abilities).length,CATALOG.abilities.length],['Compatible forms',CATALOG.transformations.filter(f=>E.getFormState(c,f.id).bandId&&E.getFormState(c,f.id).unlocked).length,CATALOG.transformations.filter(f=>E.getFormState(c,f.id).bandId).length],['Chapters mastered',c.masteredSagas.length,CATALOG.sagas.length]].map(([label,v,max])=>`<div><span>${label}</span><b>${v} / ${max}</b>${meter(v,max)}</div>`).join('')}</div>${c.achievements?.length?`<div class="achievement-list">${c.achievements.map(a=>tag(typeof a==='string'?pretty(a):a.name||a.id,'success')).join('')}</div>`:''}</section>`;}
function openDialog(title,body,cls=''){closeDialog();returnFocus=document.activeElement;const d=document.createElement('dialog');d.className=`app-dialog ${cls}`;d.innerHTML=`<header class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-content">${body}</div>`;d.setAttribute('aria-labelledby','dialog-title');$('#overlay-root').append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});d.addEventListener('close',()=>{d.remove();returnFocus?.focus?.();});d.addEventListener('cancel',event=>{if(ui.replacing)event.preventDefault();});d.showModal();d.querySelector('input:not([type=radio]),textarea,select')?.focus();return d;}
function closeDialog(force=false){if(ui.replacing&&!force)return;const d=$('dialog');if(d){d.close();d.remove();}}
function showReward(title,message,stats){openDialog(title,`<div class="reward-scene">${art('images/v7/awakening.webp','','reward-art')}<div class="reward-glow"></div><span class="reward-emblem">${icon('flame')}</span><p class="eyebrow">ANOTHER STEP ON THE LONG ROAD</p><h3>${esc(message)}</h3>${stats?`<div class="reward-stats">${Object.entries(stats).filter(([,v])=>v>0).map(([k,v])=>`<span><b>+${num(v,3)}</b><small>${esc(statNames[k]||k)}</small></span>`).join('')}</div>`:''}${btn('Keep going','close-dialog','','primary wide')}</div>`,'reward-dialog');}
function showCharacters(){openDialog('Your characters',`<p class="muted">Each origin is a separate long adventure, with its own training, partners and power.</p><div class="character-list">${Object.values(state.characters).map(c=>`<button class="character-choice ${c.id===state.activeCharacterId?'selected':''}" data-action="switch-character" data-id="${esc(c.id)}"><img ${portraitAttributes(c.routeId)} alt=""><span><b>${esc(c.name)}</b><small>${esc(routeCopy[c.routeId]?.[0])} · Level ${E.getLevel(c).level} · Power ${compact(E.getPower(c).effective)}</small></span>${c.id===state.activeCharacterId?tag('Active','success'):icon('arrow')}</button>`).join('')}</div>${btn(`${icon('plus')} Create another character`,'new-character','','primary wide')}`);}
function exerciseResults(query){return CATALOG.exercises.filter(ex=>ex.type!=='recovery_rest').filter(ex=>`${ex.name} ${ex.category} ${ex.group}`.toLowerCase().includes(query.toLowerCase())).map(ex=>`<button class="exercise-option" data-action="add-exercise" data-id="${esc(ex.id)}"><span><b>${esc(ex.name)}</b><small>${esc(ex.category)} · ${esc(ex.group)} · ${esc(ex.type)}</small></span>${icon('plus')}</button>`).join('')||empty('No exercises found.','Try a shorter search or another name.');}
function showExercises(){openDialog('Add an exercise',`<label class="search-field">Search ${CATALOG.exercises.length} exercises<input id="exercise-search" type="search" placeholder="Try bench press, walk, yoga…" autofocus></label><div class="exercise-picker" id="exercise-results">${exerciseResults('')}</div>`,'wide-dialog');}
function templateResults(query){return allTemplates().filter(t=>t.name.toLowerCase().includes(query.toLowerCase())).map(t=>`<div class="template-option"><div><b>${esc(pretty(t.name))}</b><small>${t.exercises?.length||t.entries?.length||0} exercises · ${t.builtin?'Library template':'Your template'}</small></div>${btn('Use routine','load-template',`data-id="${esc(t.id)}"`,'small')}${!t.builtin?btn('Delete','delete-template',`data-id="${esc(t.id)}"`,'text-button small danger'):''}</div>`).join('')||empty('No templates found.','Save a draft as a template to build your own library.');}
function showTemplates(){openDialog('Your workout templates',`<p class="muted">Templates are starting points. Adjust the load, sets and pace to your current training.</p><label class="search-field">Search templates<input id="template-search" type="search" placeholder="Find a routine…"></label><div id="template-results">${templateResults('')}</div>`,'wide-dialog');}
function fromTemplate(t){if(t.entries)return structuredClone(t.entries);return(t.exercises||[]).map(pair=>{const ex=CATALOG.exercises.find(e=>e.name===(Array.isArray(pair)?pair[0]:pair.name));if(!ex)return null;const raw=Array.isArray(pair)?pair[1]:pair.sets;return{exerciseId:ex.id,sets:(Array.isArray(raw)?raw:[]).map(s=>({reps:Number(s.reps||0),weight:Number(s.weight||0),seconds:Number(s.seconds||s.duration||0)})),duration:0,distance:0};}).filter(Boolean);}
function showBoosts(){const b=E.getBoosts(character());openDialog('How your training grows',`<p>Your exercise creates the base stat gains. These parts of your build multiply them together. Specific exercises may receive additional specialisation.</p>${boostRows(b)}${learningRows()}<div class="calculation-example"><span>Example</span><p>10 base points × ${num(b.race,3)} race × ${num(b.partners,3)} partners × ${num(b.equipment,3)} equipment × ${num(b.abilities,3)} abilities × ${num(b.mastery,3)} mastery</p><strong>= ${num(10*b.total,3)} permanent stat points</strong></div>${b.details?.length?`<div class="boost-details">${b.details.map(d=>`<p>${esc(typeof d==='string'?d:d.label||d.name)}${d.multiplier?` · ×${num(d.multiplier,3)}`:d.bonus?` · +${num(d.bonus*100,2)}%`:''}</p>`).join('')}</div>`:''}<p class="fine-print">Finished sessions store their build and reward receipt. Editing notes later cannot reroll them using a stronger build.</p>`);}
function showPartner(id){const p=byId(CATALOG.partners,id),s=E.getPartnerState(character(),id);openDialog(p.name,`<div class="partner-detail-hero">${partnerArt(id)}<div>${tag(p.era||'DB')}<h3>${esc(p.role)}</h3><p>${esc(effectSummary(p.effects))}</p><p>Partner Level ${s.level} · ${s.active?'Training with you':s.owned?'Recruited':'Not recruited yet'}</p></div></div><p>${esc(s.reason||'Train together to develop partner levels and training contribution.')}</p><p class="muted">Active partners develop through your logged training. Your available team slots grow through your adventure.</p>${s.owned?btn(s.active?'Remove from active team':'Add to active team','toggle-partner',`data-id="${id}"`,'primary wide'):btn(`Recruit · ${num(s.cost)} TP`,'recruit-partner',`data-id="${id}" ${s.canBuy?'':'disabled'}`,'primary wide')}`);}
function showStory(id){const entries=E.getStoryEntries(character()),e=entries.find(e=>e.id===id);if(!e){notify('That story entry has not unlocked yet.');return;}const next=entries[entries.indexOf(e)+1];openDialog(e.title,`<div class="story-reader">${e.sagaId?art(e.sagaId==='db_pilaf'?'images/v7/mountain-dawn.webp':`images/saga_banners/${e.sagaId}.webp`,'','reader-banner'):''}<p class="eyebrow">${esc(e.series||e.kind||'YOUR ADVENTURE')}</p>${String(e.text||'').split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}<div class="reader-actions">${btn(e.read?'Read':'Mark as read','mark-story',`data-id="${esc(e.id)}"`,'primary')}${next?btn('Next entry','story-reader',`data-id="${esc(next.id)}"`,'ghost'):''}</div></div>`,'reader-dialog');}
function showWorkout(id){const original=character().workouts.find(w=>w.id===id);if(!original)return;const w=getEffectivePhysicalRecord(original);openDialog(w.name||'Training session',`<p class="eyebrow">${dateLabel(w.date)} · ${w.kind==='rest'?'RECOVERY':'TRAINING'}</p>${(w.entries||[]).map(e=>`<div class="workout-entry"><h3>${esc(exById(e.exerciseId)?.name||e.name||e.exerciseId)}</h3><p>${e.duration?`${num(e.duration,1)} minutes · ${num(e.distance,2)} km`:(e.sets||[]).map(s=>s.seconds?`${num(s.seconds)} sec`:`${num(s.reps)} reps${s.weight?` × ${num(s.weight,1)} kg`:''}`).join(' / ')}</p></div>`).join('')}<div class="session-meta">${w.rpe!==null&&w.rpe!==undefined?tag(`RPE ${w.rpe}`):''}${w.rir!==null&&w.rir!==undefined?tag(`RIR ${w.rir}`):''}</div><p class="workout-notes">${esc(w.notes||'No session notes.')}</p>${w.legacy?`<p class="info-note">Original v6 gains remain in your migration balance. A physical correction updates your exercise analysis while keeping the original entry and reward evidence.</p>${w.hasPhysicalCorrection?`<p>Correction ${w.physicalCorrection.sequence} · ${esc(w.physicalCorrection.reason)}</p>`:''}${btn('Correct historical record','historical-correction',`data-id="${esc(id)}"`,'ghost')}<details><summary>Original record and correction history</summary><pre>${esc(JSON.stringify(original,null,2))}</pre></details>`:`<details class="receipt"><summary>Saved reward receipt</summary><pre>${esc(JSON.stringify(w.receipt,null,2))}</pre></details><div class="button-row">${btn('Edit notes','edit-notes',`data-id="${esc(id)}"`,'ghost')}${btn('Edit session','edit-workout',`data-id="${esc(id)}"`,'ghost')}${btn('Delete session','delete-workout',`data-id="${esc(id)}"`,'text-button danger')}</div>`}`);}
function showEditNotes(id){const w=character().workouts.find(w=>w.id===id);openDialog('Edit session notes',`<form id="notes-form" data-id="${esc(id)}"><label>Session name<input name="name" value="${esc(w.name)}" maxlength="100" required></label><label>Notes<textarea name="notes" maxlength="4000" rows="7">${esc(w.notes)}</textarea></label><p class="fine-print">Your original reward receipt and training build stay attached to this session.</p><button type="submit" class="button primary wide">Save notes</button></form>`);}
function confirm(title,text,action,id=''){openDialog(title,`<p>${esc(text)}</p><div class="button-row">${btn('Cancel','close-dialog','','ghost')}${btn('Confirm',action,`data-id="${esc(id)}"`,'danger-button')}</div>`);}
function showSettings(){openDialog('Settings & backup',`<section class="settings-section"><h3>Presentation</h3><label class="switch-row"><span><b>Motion & power effects</b><small>Respects your device’s reduced-motion preference.</small></span><input type="checkbox" id="motion-toggle" ${settings().motion!==false?'checked':''}></label><label class="switch-row"><span><b>Sound effects</b><small>Subtle cues for completed sessions and breakthroughs.</small></span><input type="checkbox" id="sound-toggle" ${settings().sound?'checked':''}></label></section><section class="settings-section"><h3>Keep your adventure safe</h3><p class="muted">Saves stay on this device. Export a backup to keep a copy elsewhere or move to another device.</p><div class="button-row">${btn('Export backup','export','','primary')}${btn('Import backup','import','','ghost')}${btn('Check snapshots','snapshots','','ghost')}</div><p class="save-status" data-save-status>${esc(ui.saveStatus)}</p></section><section class="settings-section"><h3>Your training system</h3><div class="button-row">${btn('Weekly plan','plan','','ghost')}${btn('Workout templates','templates','','ghost')}${btn('Characters','characters','','ghost')}</div></section><section class="settings-section"><h3>Offline artwork</h3><p class="muted">The story and your player portraits are included in the installed game. Keep the full collection of illustrations on this device too, including all equipment unlocks.</p>${btn('Download all artwork','cache-artwork','','ghost')}<p id="art-download-status" class="fine-print" role="status"></p></section><section class="settings-section"><h3>About this adventure</h3><p class="muted">Version 7.0 · ${CATALOG.sagas.length} sagas · ${CATALOG.partners.length} partners · ${CATALOG.abilities.length} abilities · Eight development routes.</p><p class="fine-print">Long-term progression is earned through training and investment. Rest days do not remove permanent stats. This fan project is an exercise journal and game; its power levels are fictional.</p></section>`);}
function showImport(){openDialog('Import an adventure',`<p>Choose a v7 or supported v6 backup. It will be validated before becoming the active save. A recovery snapshot protects the current v7 adventure.</p><form id="import-form"><label>Backup file<input id="import-file" type="file" accept="application/json,.json"></label><label>Or paste backup JSON<textarea id="import-text" rows="7" placeholder="Paste your exported save here…"></textarea></label><p id="import-error" class="form-error" role="alert"></p><button class="button primary wide" type="submit">Validate & import backup</button></form>`);}
async function showSnapshots(){openDialog('Recovery snapshots','<p class="muted">Loading snapshots…</p>');try{const list=await S.listSnapshots();openDialog('Recovery snapshots',`<p>Restore an earlier valid v7 snapshot. Your current adventure is preserved before restoration.</p>${list.map(s=>`<div class="snapshot-row"><span><b>${new Date(s.savedAt).toLocaleString()}</b><small>Revision ${s.revision} · ${Array.isArray(s.characters)?s.characters.length:s.characters||0} characters</small></span>${btn('Restore','confirm-restore',`data-id="${esc(s.id)}"`,'small')}</div>`).join('')||empty('No snapshots yet.','Snapshots appear as your adventure is saved.')}`);}catch(error){notify(error.message);}}
function showPlan(){const c=character(),templates=allTemplates();openDialog('Your weekly training plan',`<p class="muted">A gentle guide for your week. You can always adjust your training, skip a day or choose recovery.</p><form id="plan-form"><div class="plan-days">${[['1','Monday'],['2','Tuesday'],['3','Wednesday'],['4','Thursday'],['5','Friday'],['6','Saturday'],['0','Sunday']].map(([day,label])=>`<label>${label}<select name="day-${day}"><option value="">Open / recovery</option>${templates.map(t=>`<option value="${esc(t.id)}" ${c.plan?.[day]===t.id?'selected':''}>${esc(pretty(t.name))}</option>`).join('')}</select></label>`).join('')}</div><button class="button primary wide" type="submit">Save weekly plan</button></form>`);}
async function prepareReplacement(){clearTimeout(draftTimeout);if(!ui.fatalLoad&&Object.keys(state.characters).length&&!await persist())throw Error('The latest working draft could not be protected. Export it or fix saving before replacing this adventure.');await saveChain;clearTimeout(draftTimeout);}
const validPages=['today','train','adventure','develop','records'];
const pageFromLocation=()=>{const raw=window.location?.hash?.slice(1),aliases={training:'train','fitness-plan':'train',dashboard:'today',story:'adventure',transformations:'develop',equipment:'develop',partners:'develop',abilities:'develop'};return validPages.includes(raw)?raw:aliases[raw]||'today';};
function syncPageURL(){if(character()&&pageFromLocation()!==ui.page)window.history?.replaceState({page:ui.page},'',`#${ui.page}`);}
function navigate(page,historyChange=true){if(!validPages.includes(page))page='today';if(historyChange)window.history?.pushState({page},'',`#${page}`);clearTimeout(draftTimeout);if(ui.page==='train'&&character()?.draft)persist();ui.page=page;ui.query='';ui.filter='all';render();window.scrollTo({top:0,behavior:'instant'});}
function searchRender(){const el=document.activeElement,id=el?.id,position=el?.selectionStart,scroll=window.scrollY;render();if(id){const replacement=document.getElementById(id);replacement?.focus();try{replacement?.setSelectionRange(position,position);}catch{}}window.scrollTo({top:scroll,behavior:'instant'});}
function startTimer(seconds){draft().timerEnds=Date.now()+seconds*1000;touchDraft();clearInterval(timerInterval);timerInterval=setInterval(updateTimer,250);updateTimer();}
function updateTimer(){const display=$('#timer-display');if(!display)return;const end=character()?.draft?.timerEnds,left=end?Math.max(0,Math.ceil((end-Date.now())/1000)):90;display.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;display.classList.toggle('finished',!!end&&left===0);if(end&&left===0&&!display.dataset.announced){display.dataset.announced='yes';notify('Rest timer finished. Continue when you are ready.');clearInterval(timerInterval);}if(left>0)delete display.dataset.announced;}
async function handleAction(action,el){if(ui.replacing)return;if(ui.fatalLoad&&!['retry-load','import','close-dialog','snapshots','confirm-restore','restore-snapshot'].includes(action))return;if(action==='close-dialog'&&planner.requestClose?.())return;if(await planner.handleAction(action,el))return;if(await restored.handleAction(action,el))return;const id=el.dataset.id,c=character();switch(action){
case 'restore-load-routine':if(pendingRoutine){c.draft={...freshDraft(),entries:pendingRoutine.entries,name:pendingRoutine.name};pendingRoutine=null;ui.page='train';epoch++;if(await persist()){closeDialog();render();notify('Routine loaded. Record what you complete.');}}break;
case 'nav':navigate(id);break;
case 'develop-tab':ui.page='develop';ui.develop=id;ui.query='';ui.filter='all';render();window.scrollTo({top:0,behavior:'instant'});break;
case 'adventure-tab':ui.adventure=id;ui.query='';ui.filter='all';render();break;
case 'records-tab':ui.records=id;ui.query='';ui.filter='all';render();break;
case 'close-dialog':closeDialog();break;
case 'characters':showCharacters();break;
case 'new-character':openDialog('A new origin, a new journey',characterForm(),'wide-dialog');break;
case 'switch-character':closeDialog();await commit(()=>{state.activeCharacterId=id;ui.page='today';},'Character switched.');break;
case 'settings':showSettings();break;
case 'cache-artwork':{el.disabled=true;try{const result=await cacheArtwork({onProgress:p=>{const output=$('#art-download-status');if(output)output.textContent=`Keeping ${p.completed} / ${p.total} illustrations…`;}});const output=$('#art-download-status');if(output)output.textContent=result.failures.length?`${result.failures.length} images could not be downloaded. Completed artwork is available offline; retry when online.`:'Your complete illustration collection is ready offline.';}catch(error){notify(error.message);}finally{el.disabled=false;}break;}
case 'retry-save':await persist();break;
case 'retry-load':await boot();break;
case 'dismiss-migration':await commit(()=>{settings().migrationDismissed=true;ui.migration=null;});break;
case 'boosts':showBoosts();break;
case 'exercises':showExercises();break;
case 'add-exercise':{const ex=exById(id);draft().entries.push({exerciseId:id,sets:isCardio(ex)?[]:[{reps:isTimed(ex)?0:10,weight:0,seconds:isTimed(ex)?60:0}],duration:isCardio(ex)?20:0,distance:0});touchDraft();closeDialog();render();break;}
case 'remove-exercise':draft().entries.splice(Number(el.dataset.index),1);touchDraft();render();break;
case 'add-set':{const sets=draft().entries[Number(el.dataset.index)].sets;sets.push({...sets.at(-1)||{reps:10,weight:0,seconds:0}});touchDraft();render();break;}
case 'remove-set':draft().entries[Number(el.dataset.index)].sets.splice(Number(el.dataset.set),1);touchDraft();render();break;
case 'templates':planner.openTemplates();break;
case 'load-template':{const t=allTemplates().find(t=>t.id===id||t.name===id);if(!t)throw Error('Template not found.');if(c.draft?.entries?.length)openDialog('Use this routine?',`<p>This replaces the exercises in your current draft with ${esc(pretty(t.name))}.</p><div class="button-row">${btn('Keep draft','close-dialog','','ghost')}${btn('Use routine','apply-template',`data-id="${esc(t.id)}"`,'primary')}</div>`);else await handleAction('apply-template',el);break;}
case 'apply-template':{const t=allTemplates().find(t=>t.id===id||t.name===id);c.draft={...freshDraft(),name:pretty(t.name),entries:fromTemplate(t)};ui.page='train';touchDraft();closeDialog();render();notify('Routine loaded. Adjust the weights to suit your training.');break;}
case 'save-template':if(!draft().entries.length)throw Error('Add an exercise before saving a template.');planner.saveDraftAsTemplate(draft().entries,draft().name);break;
case 'delete-template':await commit(()=>{state.templates=state.templates.filter(t=>t.id!==id);},'Template deleted.');showTemplates();break;
case 'discard-draft':confirm('Discard this draft?','Only the unfinished session will be removed. Your saved training history stays intact.','confirm-discard');break;
case 'confirm-discard':closeDialog();await commit(()=>{c.draft=null;ui.page='today';},'Draft discarded.');break;
case 'finish-workout':{if(c?.draft?.legacyCorrectionId){const input=structuredClone(c.draft),wid=input.legacyCorrectionId,patch=Object.fromEntries(['date','kind','name','notes','rpe','rir','entries','recovery'].map(k=>[k,input[k]]));if(await commit(()=>{const result=createLegacyCorrection(c,wid,patch,input.correctionReason);c.workouts[c.workouts.findIndex(w=>w.id===wid)]=result.workout;c.draft=null;ui.page='records';ui.records='history';},'Historical correction saved. Original gains preserved.'))showWorkout(wid);break;}if(ui.finishing||!c?.draft)return;ui.finishing=true;try{const input=structuredClone(c.draft),before={...c.stats};let savedWorkoutId=input.editId;if(await commit(()=>{if(input.editId)E.editWorkout(c,input.editId,input);else savedWorkoutId=E.logWorkout(c,input).id;c.draft=null;ui.page='today';},'Session saved.','workout'))restored.showReceipt(savedWorkoutId);}finally{ui.finishing=false;}break;}
case 'rest':openDialog('A day for recovery',`<form id="rest-form"><p>Rest belongs in a long training journey. Record the day without losing any permanent power.</p><label>Date<input type="date" name="date" value="${E.localDate()}" max="${E.localDate()}" required></label><label>Notes<textarea name="notes" rows="3" maxlength="4000" placeholder="How are you feeling?"></textarea></label><button class="button primary wide" type="submit">Save recovery day</button></form>`);break;
case 'timer-entry':startTimer(Number(draft().entries[Number(el.dataset.index)].restSeconds||90));break;
case 'timer-start':startTimer(Number(el.dataset.seconds));break;
case 'timer-reset':delete draft().timerEnds;clearInterval(timerInterval);touchDraft();updateTimer();break;
case 'partner-detail':restored.showPartner(id);break;
case 'recruit-partner':closeDialog();await commit(()=>E.recruitPartner(c,id),'Partner recruited. Your active team is shown in the collection.','purchase');break;
case 'toggle-partner':closeDialog();await commit(()=>E.togglePartner(c,id),'Training team updated.');break;
case 'buy-equipment':await commit(()=>E.buyEquipment(c,id),'Equipment developed. Your next training date uses the stronger build.','purchase');break;
case 'buy-ability':await commit(()=>E.buyAbility(c,id),'Technique developed.','purchase');break;
case 'toggle-ability':await commit(()=>E.toggleAbility(c,id),'Equipped techniques updated.');break;
case 'unlock-form':if(await commit(()=>E.unlockForm(c,id),'Transformation unlocked.','awakening'))showReward('A new possibility',byId(CATALOG.transformations,id)?.name);break;
case 'equip-release':await commit(()=>E.equipRelease(c),'Native race release selected.');break;
case 'equip-form':closeDialog();await commit(()=>E.equipForm(c,id),'Current form updated.');break;
case 'awaken':if(await commit(()=>E.awaken(c,id),'A new state is yours.','awakening'))showReward('Breakthrough','An earned awakening. A new chapter of training.');break;
case 'set-branch':await commit(()=>E.setBranch(c,$('#race-branch').value),'Training specialisation updated.');break;
case 'equip-core':await commit(()=>E.equipCore(c,$('#core-partner').value),'Development selection updated.');break;
case 'clear-saga':if(await commit(()=>E.clearSaga(c,id),'Chapter completed.','saga'))showReward('Chapter complete',sagaName(id));break;
case 'set-focus-saga':await commit(()=>E.setFocusSaga(c,$('#focus-saga').value||null),'Training focus updated for your next training date.');break;
case 'replay-saga':await commit(()=>E.replaySaga(c,id),'Chapter replay completed.','saga');break;
case 'master-saga':await commit(()=>E.masterSaga(c,id),'Chapter mastery earned.','saga');break;
case 'saga-story':{const entries=E.getStoryEntries(c).filter(e=>e.sagaId===id);if(entries.length)openDialog(sagaName(id),`<div class="chapter-entry-list">${entries.map(e=>`<button class="activity-row" data-action="story-reader" data-id="${esc(e.id)}"><span>${icon('book')}</span><span><b>${esc(e.title)}</b><small>${e.read?'Read':'Unread'}</small></span>${icon('arrow')}</button>`).join('')}</div>`);else notify('More story appears as you develop chapter focus.');break;}
case 'story-reader':showStory(id);break;
case 'mark-story':await commit(()=>E.markStoryRead(c,id),'Story marked as read.');showStory(id);break;
case 'wish':if(await commit(()=>E.makeWish(c,id),'Your wish has been granted.','wish'))showReward('Wish granted','Another search begins with seven small discoveries.');break;
case 'historical-correction':{if(c.draft?.entries?.length)throw Error('Save or discard your current draft before correcting history.');const original=c.workouts.find(w=>w.id===id);const w=getEffectivePhysicalRecord(original);c.draft={...freshDraft(),date:w.date,kind:w.kind,name:w.name,notes:w.notes||'',rpe:w.rpe??null,rir:w.rir??null,recovery:w.recovery||{},entries:structuredClone(w.entries||[]),legacyCorrectionId:id,correctionReason:''};closeDialog();ui.page='train';touchDraft();render();break;}
case 'workout-detail':showWorkout(id);break;
case 'edit-notes':showEditNotes(id);break;
case 'edit-workout':{if(c.draft?.entries?.length)throw Error('Save or discard your current draft before editing a past session.');const w=c.workouts.find(w=>w.id===id);if(w.legacy)throw Error('Imported sessions remain a read-only archive.');c.draft={...structuredClone(w),editId:id};closeDialog();ui.page='train';touchDraft();render();break;}
case 'delete-workout':confirm('Delete this session?','This removes the session and reconciles its earned rewards. Your remaining history is kept.','confirm-delete-workout',id);break;
case 'confirm-delete-workout':closeDialog();await commit(()=>E.deleteWorkout(c,id),'Session deleted and rewards reconciled.');break;
case 'delete-body':await commit(()=>{c.bodyWeightLog=c.bodyWeightLog.filter(w=>(w.id||w.date)!==id);},'Measurement removed.');break;
case 'plan':planner.openPlan();break;
case 'export':{const text=S.exportGame(state),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`dragon-ball-fitness-v7-${E.localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup export created.');break;}
case 'import':showImport();break;
case 'snapshots':await showSnapshots();break;
case 'confirm-restore':confirm('Restore this snapshot?','The selected snapshot becomes your active adventure. A recovery copy protects the current save.','restore-snapshot',id);break;
case 'restore-snapshot':{ui.replacing=true;try{state=await S.restoreSnapshot(id,{beforeRestore:prepareReplacement});epoch++;ui.fatalLoad=false;ui.error='';ui.saveStatus='Snapshot restored';ui.page='today';closeDialog(true);render();notify('Recovery snapshot restored.');}finally{ui.replacing=false;}break;}
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();handleAction(el.dataset.action,el).catch(error=>notify(error.message||'This action could not be completed.'));});
document.addEventListener('input',event=>{if(ui.replacing||ui.fatalLoad)return;if(planner.handleInput(event)||restored.handleInput(event))return;const el=event.target,c=character();if(el.id==='exercise-search'){$('#exercise-results').innerHTML=exerciseResults(el.value);return;}if(el.id==='template-search'){$('#template-results').innerHTML=templateResults(el.value);return;}if(el.hasAttribute('data-query')){ui.query=el.value;searchRender();return;}if(el.name==='routeId'){const desc=$('#route-description');if(desc)desc.textContent=routeCopy[el.value]?.[1]||'';return;}if(el.dataset.draft){const key=el.dataset.draft;draft()[key]=['rpe','rir'].includes(key)?el.value===''?null:Number(el.value):el.value;touchDraft();return;}if(el.dataset.entry!==undefined){const entry=draft().entries[Number(el.dataset.entry)];if(el.dataset.set!==undefined)entry.sets[Number(el.dataset.set)][el.dataset.setField]=el.value===''?0:Number(el.value);else entry[el.dataset.entryField]=el.dataset.entryField==='notes'?el.value:el.value===''?0:Number(el.value);touchDraft();return;}if(el.dataset.recovery){draft().recovery||={};draft().recovery[el.dataset.recovery]=el.checked;touchDraft();}});
document.addEventListener('change',async event=>{if(ui.replacing||ui.fatalLoad)return;if(await planner.handleChange(event)||restored.handleChange(event))return;const el=event.target;if(el.hasAttribute('data-filter')){ui.filter=el.value;searchRender();}if(el.id==='motion-toggle'){settings().motion=el.checked;epoch++;document.documentElement.dataset.motion=el.checked?'on':'off';persist();}if(el.id==='sound-toggle'){settings().sound=el.checked;epoch++;persist();}});
document.addEventListener('submit',async event=>{if(ui.replacing){event.preventDefault();return;}if(await planner.handleSubmit(event)||await restored.handleSubmit(event))return;const form=event.target;if(!['character-form','template-form','rest-form','notes-form','body-form','plan-form','import-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form),c=character();try{
if(form.id==='character-form'){if(ui.fatalLoad)return;const options={name:String(data.get('name')).trim(),routeId:data.get('routeId')};if(!options.name)throw Error('Give your character a name.');closeDialog();await commit(()=>{E.createCharacter(state,options);ui.page='today';},'Your adventure begins.');}
if(form.id==='template-form'){const name=String(data.get('name')).trim();if(!name)throw Error('Give the template a name.');await commit(()=>{state.templates.push({id:crypto.randomUUID(),name,entries:structuredClone(draft().entries),createdAt:new Date().toISOString()});},'Workout template saved.');closeDialog();}
if(form.id==='rest-form'){const input={date:data.get('date'),name:'Recovery day',kind:'rest',notes:data.get('notes'),rpe:null,rir:null,entries:[]};closeDialog();await commit(()=>E.logWorkout(c,input),'Recovery day saved.');}
if(form.id==='notes-form'){const id=form.dataset.id;closeDialog();await commit(()=>E.editWorkout(c,id,{name:data.get('name'),notes:data.get('notes')}),'Session notes saved.');}
if(form.id==='body-form'){const date=data.get('date'),weight=Number(data.get('weight'));E.validateWorkout({date,name:'Measurement date check',kind:'rest',entries:[]});if(!Number.isFinite(weight)||weight<20||weight>500)throw Error('Enter a weight between 20 and 500 kg.');await commit(()=>{c.bodyWeightLog=c.bodyWeightLog.filter(w=>w.date!==date);c.bodyWeightLog.push({id:crypto.randomUUID(),date,weight});},'Body weight recorded.');}
if(form.id==='plan-form'){closeDialog();await commit(()=>{c.plan=Object.fromEntries(Array.from({length:7},(_,day)=>[day,data.get(`day-${day}`)||'']));},'Weekly plan saved.');}
if(form.id==='import-form'){const file=$('#import-file').files[0];let text=$('#import-text').value;if(file){if(file.size>40*1024*1024)throw Error('Choose a backup no larger than 40 MB.');text=await file.text();}if(!text.trim())throw Error('Choose a backup file or paste its contents.');const submit=$('button[type="submit"]',form);submit.disabled=true;submit.textContent='Validating and saving…';ui.replacing=true;try{await prepareReplacement();const result=await S.importGame(text);state=result.state;epoch++;ui.fatalLoad=false;ui.migration=result.report?.sourceSchema<70?result.report:null;ui.page='today';ui.error='';ui.saveStatus='Imported and saved';closeDialog(true);render();notify('Backup imported successfully.');}catch(error){$('#import-error').textContent=error.message;submit.disabled=false;submit.textContent='Validate & import backup';}finally{ui.replacing=false;}}
}catch(error){if(form.id==='import-form'&&$('#import-error'))$('#import-error').textContent=error.message;else notify(error.message);}});
document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&!img.dataset.fallback){img.dataset.fallback='true';const label=document.createElement('span');label.className='art-unavailable';label.textContent=img.alt?`${img.alt} · artwork unavailable`:'Artwork unavailable';img.replaceWith(label);}},true);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&character()?.draft)persist();if(document.visibilityState==='visible')updateTimer();});
window.addEventListener('popstate',()=>{if(!ui.fatalLoad)navigate(pageFromLocation(),false);});
window.addEventListener('pagehide',()=>{if(character()?.draft)persist();});
S.subscribeToExternalChanges?.(()=>{ui.error='Another tab has saved a newer adventure. Export any unsaved work here, then reload to continue with the latest save.';ui.saveStatus='Another tab changed this save';saveIndicator();});
async function prepareUpdateReload(){
  const editing=()=>ui.replacing||ui.finishing||ui.fatalLoad||!ui.booted||document.querySelector('dialog[open]')||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');
  if(editing())return false;
  const before=epoch;
  clearTimeout(draftTimeout);
  if(Object.keys(state.characters).length&&!await persist())return false;
  await saveChain;
  return epoch===before&&!editing()&&ui.saveStatus!=='Changes not saved';
}
const appUpdates=startUpdateChecks({beforeReload:prepareUpdateReload,onDeferred:()=>{if(ui.booted)notify('An update is ready. Finish editing, then reopen the app to use it.');}});
async function boot(){try{const loaded=await S.loadGame(),recoveredDrafts=draftRecovery.recover(loaded.state||E.createState());state=recoveredDrafts.state;ui.fatalLoad=false;ui.page=pageFromLocation();ui.migration=settings().migrationDismissed?null:loaded.migrationReport||null;ui.error=[loaded.warning,recoveredDrafts.warning].filter(Boolean).join(' ');ui.saveStatus=loaded.state?`Loaded from ${loaded.source||'this device'}`:'Ready for your first chapter';render();if(loaded.migrationReport||recoveredDrafts.recovered.length){epoch++;const saved=await persist();if(saved&&recoveredDrafts.recovered.length)notify('Your latest unfinished workout was recovered and saved.');}if(character()?.draft?.timerEnds)timerInterval=setInterval(updateTimer,250);ui.booted=true;await appUpdates.applyReady();}catch(error){ui.fatalLoad=true;ui.error=error.message;ui.saveStatus='Could not load save';render();saveIndicator();}}
boot();
